        # left/right offset indicates which side of the object to copy toward.
        bar_mid = (min(bar_cols) + max(bar_cols)) / 2
        down = stem_c > bar_mid
        for r, c in fours:
            rr = 2 * max_r + 1 - r if down else 2 * min_r - 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
